149	  "scan_id" | "pillar" | "score" | "weight"
150	> &
151	  Partial<Omit<ScanResultRow, "scan_id" | "pillar" | "score" | "weight" | "id" | "created_at">>;
152	
153	export type IntegrationInsert = Pick<
154	  IntegrationRow,
155	  "user_id" | "provider"
156	> &
