158	
159	// ── Update types (all fields optional except primary key) ─────
160	
161	export type ProfileUpdate = Partial<
162	  Omit<ProfileRow, "id" | "created_at">
163	>;
164	
165	export type ScanUpdate = Partial<Omit<ScanRow, "id" | "user_id" | "created_at">>;
166	
167	export type ScanResultUpdate = Partial<
168	  Omit<ScanResultRow, "id" | "scan_id" | "pillar" | "created_at">
169	>;
170	
171	export type IntegrationUpdate = Partial<
172	  Omit<IntegrationRow, "id" | "user_id" | "provider" | "connected_at">
173	>;
174	
175	// ── Supabase Database generic type ────────────────────────────
176	
177	export interface Database {
178	  public: {
179	    Tables: {
180	      profiles: {
181	        Row: ProfileRow;
182	        Insert: ProfileInsert;
183	        Update: ProfileUpdate;
184	      };
185	      scans: {
186	        Row: ScanRow;
187	        Insert: ScanInsert;
188	        Update: ScanUpdate;
189	      };
190	      scan_results: {
191	        Row: ScanResultRow;
192	        Insert: ScanResultInsert;
193	        Update: ScanResultUpdate;
194	      };
195	      integrations: {
196	        Row: IntegrationRow;
197	        Insert: IntegrationInsert;
198	        Update: IntegrationUpdate;
199	      };
200	      copy_rewrites: {
201	        Row: CopyRewriteRow;
202	        Insert: CopyRewriteInsert;
203	        Update: CopyRewriteUpdate;
204	      };
205	      audit_logs: {
206	        Row: AuditLogRow;
207	        Insert: AuditLogInsert;
208	        Update: Partial<Omit<AuditLogRow, "id" | "created_at">>;
209	      };
210	      scan_history: {
211	        Row: ScanHistoryInsert & { id: string };
212	        Insert: ScanHistoryInsert;
213	        Update: Partial<ScanHistoryInsert>;
214	      };
215	    };
216	    Views: Record<string, never>;
217	    Functions: {
218	      increment_scan_usage: {
219	        Args: { user_uuid: string };
220	        Returns: boolean;
221	      };
222	      reset_monthly_scans: {
223	        Args: Record<string, never>;
224	        Returns: void;
225	      };
226	      is_admin: {
227	        Args: Record<string, never>;
228	        Returns: boolean;
229	      };
230	    };
231	    Enums: Record<string, never>;
232	  };
233	}
234	
235	// ── Convenience helpers ───────────────────────────────────────
236	// Use these for typed Supabase client access.
237	
238	export type Tables<T extends keyof Database["public"]["Tables"]> =
239	  Database["public"]["Tables"][T]["Row"];
240	
241	export type TablesInsert<T extends keyof Database["public"]["Tables"]> =
242	  Database["public"]["Tables"][T]["Insert"];
243	
244	export type TablesUpdate<T extends keyof Database["public"]["Tables"]> =
245	  Database["public"]["Tables"][T]["Update"];
246	
247	export type DbFunctions = Database["public"]["Functions"];
