126	function CopyButton({ text }: { text: string }) {
127	  const [copied, setCopied] = useState(false);
128	  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
129	
130	  useEffect(() => () => { if (timerRef.current) clearTimeout(timerRef.current); }, []);
131	
132	  const handleCopy = async () => {
133	    if (timerRef.current) clearTimeout(timerRef.current);
134	    try {
135	      await navigator.clipboard.writeText(text);
136	    } catch {
137	      const textarea = document.createElement("textarea");
138	      textarea.value = text;
139	      document.body.appendChild(textarea);
140	      textarea.select();
141	      document.execCommand("copy");
142	      document.body.removeChild(textarea);
143	    }
144	    setCopied(true);
145	    timerRef.current = setTimeout(() => setCopied(false), 2000);
146	  };
147	
148	  return (
149	    <TooltipProvider delayDuration={200}>
