92	              {getEffortLabel(finding.effort)}
93	            </span>
94	            {/* Lift badge */}
95	            {finding.estimated_lift && finding.estimated_lift !== "0%" && (
96	              <span className="hidden sm:inline-flex items-center gap-0.5 rounded-full border border-violet-200 bg-violet-50 px-2 py-0.5 text-2xs font-semibold uppercase tracking-wide text-violet-600">
