217	        Insert: CopyRewriteInsert;
218	        Update: CopyRewriteUpdate;
219	      };
220	      audit_logs: {
221	        Row: AuditLogRow;
222	        Insert: AuditLogInsert;
223	        Update: Partial<Omit<AuditLogRow, "id" | "created_at">>;
224	      };
225	      scan_history: {
226	        Row: ScanHistoryInsert & { id: string };
227	        Insert: ScanHistoryInsert;
228	        Update: Partial<ScanHistoryInsert>;
229	      };
230	      competitor_groups: {
231	        Row: CompetitorGroupRow;
232	        Insert: CompetitorGroupInsert;
233	        Update: Partial<Omit<CompetitorGroupRow, "id" | "user_id" | "created_at">>;
234	      };
235	      competitor_urls: {
236	        Row: CompetitorUrlRow;
237	        Insert: CompetitorUrlInsert;
238	        Update: CompetitorUrlUpdate;
239	      };
240	    };
241	    Views: Record<string, never>;
242	    Functions: {
243	      increment_scan_usage: {
244	        Args: { user_uuid: string };
245	        Returns: boolean;
246	      };
247	      reset_monthly_scans: {
248	        Args: Record<string, never>;
249	        Returns: void;
250	      };
251	      is_admin: {
252	        Args: Record<string, never>;
253	        Returns: boolean;
254	      };
255	    };
256	    Enums: Record<string, never>;
257	  };
258	}
259	
260	// ── Convenience helpers ───────────────────────────────────────
261	// Use these for typed Supabase client access.
262	
263	export type Tables<T extends keyof Database["public"]["Tables"]> =
264	  Database["public"]["Tables"][T]["Row"];
265	
266	export type TablesInsert<T extends keyof Database["public"]["Tables"]> =
267	  Database["public"]["Tables"][T]["Insert"];
