import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import type { PillarResult, Scan } from "@/types";
import type { DbFinding, ScanResultRow } from "@/types/database";
import type { Finding } from "@/types";

// ── Query keys ──────────────────────────────────────────────────

export const shareReportKeys = {
  publicScan: (token: string) => ["public-scan", token] as const,
};

// ── Public report payload shape (from edge function) ────────────

export interface PublicScanPayload {
  scan: Omit<Scan, "user_id">;
  results: PillarResult[];
}

// ── useGenerateShareLink ────────────────────────────────────────

export function useGenerateShareLink() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (scanId: string): Promise<string> => {
      const token = crypto.randomUUID();
      const { error } = await supabase
        .from("scans")
        .update({ share_token: token, is_public: true })
        .eq("id", scanId);

      if (error) throw new Error(error.message);

      return `${window.location.origin}/r/${token}`;
    },
    onSuccess: (_url, scanId) => {
      // Invalidate so useScan refetches updated share_token + is_public
      queryClient.invalidateQueries({ queryKey: ["scans", scanId] });
      queryClient.invalidateQueries({ queryKey: ["scans"] });
    },
  });
}

// ── useRevokeShareLink ──────────────────────────────────────────

export function useRevokeShareLink() {
  const queryClient = useQueryClient();

  return useMutation({
    mutationFn: async (scanId: string): Promise<void> => {
      const { error } = await supabase
        .from("scans")
        .update({ share_token: null, is_public: false })
        .eq("id", scanId);

      if (error) throw new Error(error.message);
    },
    onSuccess: (_data, scanId) => {
      queryClient.invalidateQueries({ queryKey: ["scans", scanId] });
      queryClient.invalidateQueries({ queryKey: ["scans"] });
    },
  });
}

// ── usePublicScan ───────────────────────────────────────────────

function dbFindingToFinding(f: DbFinding): Finding {
  return {
    id: f.id,
    title: f.title,
    severity: f.severity,
    current_state: f.current_state,
    recommendation: f.recommendation,
    ai_suggestion: f.ai_suggestion,
    is_premium: f.is_premium,
    effort: f.effort,
    estimated_lift: f.estimated_lift,
    category: f.category,
  };
}

function rowToPillarResult(row: ScanResultRow): PillarResult {
  return {
    id: row.id,
    scan_id: row.scan_id,
    pillar: row.pillar,
    score: row.score,
    weight: row.weight,
    benchmark: row.benchmark,
    findings: (row.findings ?? []).map(dbFindingToFinding),
  };
}

export function usePublicScan(token: string) {
  return useQuery({
    queryKey: shareReportKeys.publicScan(token),
    queryFn: async (): Promise<PublicScanPayload> => {
      const supabaseUrl = import.meta.env.VITE_SUPABASE_URL as string;
      const supabaseKey = (
        (import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string | undefined) ??
        (import.meta.env.VITE_SUPABASE_ANON_KEY as string | undefined)
      );

      if (!supabaseUrl || !supabaseKey) {
        throw new Error("Missing Supabase environment variables");
      }

      const res = await fetch(
        `${supabaseUrl}/functions/v1/public-report?token=${encodeURIComponent(token)}`,
        {
          headers: {
            apikey: supabaseKey,
            "Content-Type": "application/json",
          },
        }
      );

      if (res.status === 404) {
        throw new Error("NOT_FOUND");
      }

      if (!res.ok) {
        throw new Error(`Failed to load public report: ${res.status}`);
      }

      const json = (await res.json()) as {
        scan: Omit<Scan, "user_id">;
        results: ScanResultRow[];
      };

      return {
        scan: json.scan,
        results: json.results.map(rowToPillarResult),
      };
    },
    enabled: !!token,
    staleTime: 1000 * 60 * 5,
    retry: (failureCount, error) => {
      if (error instanceof Error && error.message === "NOT_FOUND") return false;
      return failureCount < 2;
    },
  });
}

import { useQuery } from "@tanstack/react-query";
import supabase from "@/lib/supabase";
import type { CroPillar, IndustryType } from "@/types";
import type { IndustryBenchmarkRow } from "@/types/database";

// ── Query keys ──────────────────────────────────────────────────

export const benchmarkKeys = {
  all: ["industry-benchmarks"] as const,
  byIndustryAndPage: (industry: IndustryType, pageType: string) =>
    ["industry-benchmarks", industry, pageType] as const,
  industries: ["industry-benchmarks", "distinct-industries"] as const,
};

// ── Benchmark result shape ───────────────────────────────────────

export interface PillarBenchmark {
  avg_score: number;
  sample_size: number;
}

// ── useIndustryBenchmarks ───────────────────────────────────────

export function useIndustryBenchmarks(industry: IndustryType, pageType: string) {
  return useQuery({
    queryKey: benchmarkKeys.byIndustryAndPage(industry, pageType),
    queryFn: async (): Promise<Record<CroPillar, PillarBenchmark>> => {
      const { data, error } = await supabase
        .from("industry_benchmarks")
        .select("*")
        .eq("industry", industry)
        .eq("page_type", pageType);

      if (error) throw new Error(error.message);

      const rows = (data ?? []) as IndustryBenchmarkRow[];

      // Build a map keyed by pillar — fall back to empty object if no rows
      const result: Partial<Record<CroPillar, PillarBenchmark>> = {};
      for (const row of rows) {
        result[row.pillar as CroPillar] = {
          avg_score: row.avg_score,
          sample_size: row.sample_size,
        };
      }

      return result as Record<CroPillar, PillarBenchmark>;
    },
    enabled: !!industry && !!pageType,
    staleTime: 1000 * 60 * 60, // benchmarks rarely change — 1 hour cache
  });
}

// ── useAvailableIndustries ──────────────────────────────────────

export function useAvailableIndustries() {
  return useQuery({
    queryKey: benchmarkKeys.industries,
    queryFn: async (): Promise<IndustryType[]> => {
      const { data, error } = await supabase
        .from("industry_benchmarks")
        .select("industry");

      if (error) throw new Error(error.message);

      const distinct = Array.from(
        new Set((data ?? []).map((r: { industry: string }) => r.industry))
      ) as IndustryType[];

      return distinct;
    },
    staleTime: 1000 * 60 * 60,
  });
}

/**
 * public-report — Edge Function
 *
 * Serves a public CRO audit report for a given share token.
 * No auth required. Uses service_role to bypass RLS.
 *
 * GET ?token=<share_token>
 *
 * Returns:
 *   { scan: SanitizedScan, results: ScanResultRow[] }
 *
 * Required env vars:
 *   SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY
 */

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

// ── CORS headers ──────────────────────────────────────────────

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "GET, OPTIONS",
};

function corsResponse(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), {
    status,
    headers: { ...corsHeaders, "Content-Type": "application/json" },
  });
}

// ── DB row shapes (local — no shared imports in edge functions) ─

interface ScanRow {
  id: string;
  user_id: string;
  url: string;
  favicon_url: string | null;
  page_title: string | null;
  page_type: string;
  status: string;
  overall_score: number | null;
  issues_found: number;
  critical_issues: number;
  warnings: number;
  quick_wins: number;
  screenshot_url: string | null;
  device: string;
  share_token: string | null;
  is_public: boolean;
  created_at: string;
  completed_at: string | null;
}

interface DbFinding {
  id: string;
  title: string;
  severity: string;
  current_state: string;
  recommendation: string;
  ai_suggestion: string;
  is_premium: boolean;
  effort: string;
  estimated_lift: string;
  category: string;
}

interface ScanResultRow {
  id: string;
  scan_id: string;
  pillar: string;
  score: number;
  weight: number;
  benchmark: number;
  findings: DbFinding[];
  fixed_findings: string[];
  created_at: string;
}

// Sanitize scan: remove user_id, keep only public-safe fields
type SanitizedScan = Omit<ScanRow, "user_id">;

function sanitizeScan(row: ScanRow): SanitizedScan {
  const { user_id: _removed, ...rest } = row;
  return rest;
}

// Filter findings: remove premium ones if the scan was on a free plan
// Since we don't know the plan here, we expose all non-premium findings
// Premium findings have ai_suggestion blurred on the client side anyway
function sanitizeResults(results: ScanResultRow[]): ScanResultRow[] {
  return results.map((r) => ({
    ...r,
    findings: r.findings.filter((f) => !f.is_premium),
  }));
}

// ── Handler ───────────────────────────────────────────────────

serve(async (req: Request) => {
  // Preflight
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  if (req.method !== "GET") {
    return corsResponse({ error: "Method not allowed" }, 405);
  }

  const url = new URL(req.url);
  const token = url.searchParams.get("token");

  if (!token || token.trim() === "") {
    return corsResponse({ error: "Missing token" }, 400);
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");

  if (!supabaseUrl || !serviceKey) {
    return corsResponse({ error: "Server configuration error" }, 500);
  }

  // Use service_role client to bypass RLS
  const adminClient = createClient(supabaseUrl, serviceKey, {
    auth: { persistSession: false },
  });

  // Fetch scan by share_token
  const { data: scanData, error: scanError } = await adminClient
    .from("scans")
    .select("*")
    .eq("share_token", token)
    .eq("is_public", true)
    .maybeSingle();

  if (scanError) {
    return corsResponse({ error: "Database error" }, 500);
  }

  if (!scanData) {
    return corsResponse({ error: "Report not found or no longer public" }, 404);
  }

  const scan = scanData as ScanRow;

  // Fetch scan results
  const { data: resultsData, error: resultsError } = await adminClient
    .from("scan_results")
    .select("*")
    .eq("scan_id", scan.id);

  if (resultsError) {
    return corsResponse({ error: "Failed to load report results" }, 500);
  }

  const results = (resultsData ?? []) as ScanResultRow[];

  return corsResponse({
    scan: sanitizeScan(scan),
    results: sanitizeResults(results),
  });
});

